@Redirect(
        method = "renderTitle",
        at = @At(value = "INVOKE",
                target = "Lnet/minecraft/client/gui/GuiGraphics;drawString"
                        + "(Lnet/minecraft/client/gui/Font;Lnet/minecraft/network/chat/Component;III)I"),
        require = 0)
private int nyanlex$title(GuiGraphics g, Font font, Component text, int x, int y, int color) {
    if (!HookGuard.enter("GuiScoreboard.title")) return g.drawString(font, text, x, y, color);
    try {
        TranslationService s = NyanLexFabric.service();
        return nyanlex$backdrop("title", g, font, text, x, y, font.width(text), color, s == null ? null : s::translateTitle);
    } catch (Throwable guardError) {
        HookGuard.fail("GuiScoreboard.title", guardError);
        return g.drawString(font, text, x, y, color);
    }
}

